{
  "name": "Symbolic Tank Warfare by Gemdori",
  "description": "A minimalist 2D symbol-style tank game developed with a 20-year veteran's touch. Features sleek mechanics, strategic AI, and real-time advice from 'Gemdori' using Gemini AI.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum GameStatus {
  START = 'START',
  PLAYING = 'PLAYING',
  GAMEOVER = 'GAMEOVER',
  LEVEL_UP = 'LEVEL_UP'
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector;
  velocity: Vector;
  radius: number;
  angle: number;
  health: number;
  maxHealth: number;
}

export interface Tank extends Entity {
  type: 'player' | 'enemy';
  cooldown: number;
  score: number;
  speed: number;
}

export interface Bullet extends Entity {
  ownerId: string;
  damage: number;
}

export interface Particle {
  id: string;
  pos: Vector;
  velocity: Vector;
  life: number;
  color: string;
}

export interface GameState {
  player: Tank;
  enemies: Tank[];
  bullets: Bullet[];
  particles: Particle[];
  level: number;
  status: GameStatus;
  advice: string;
}

export const CANVAS_WIDTH = 800;
export const CANVAS_HEIGHT = 600;

export const PLAYER_SPEED = 3.5;
export const PLAYER_RADIUS = 18;
export const ENEMY_RADIUS = 18;
export const BULLET_SPEED = 7;
export const BULLET_RADIUS = 4;
export const SHOOT_COOLDOWN = 20;

export const COLORS = {
  PLAYER: '#38bdf8', // Sky Blue
  ENEMY: '#f87171',  // Red
  BULLET: '#fbbf24', // Amber
  BG: '#0f172a',     // Slate 900
  GRID: '#1e293b',   // Slate 800
  ACCENT: '#4ade80'  // Green
};

export const INITIAL_ADVICE = "여어- 신입. 탱크 조종은 처음인가? 화면을 클릭해서 쏘고 WASD로 움직여봐. '겜돌이'가 지켜보고 있다고!";

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getGemdoriAdvice = async (gameState: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `당신은 20년차 전설적인 게임 개발자 '겜돌이'입니다. 말투는 거칠지만 정이 넘치는 아저씨 개발자 톤입니다. 
      현재 탱크 게임 상황: ${gameState}. 
      플레이어에게 짧고 강렬한 팁이나 응원, 혹은 독설을 한 마디 해주세요. (한국어로, 최대 2문장)`,
      config: {
        temperature: 0.8,
        topP: 0.9,
      }
    });
    return response.text || "그냥 쏴! 생각하지 말고!";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "서버가 좀 아프네... 그냥 내 감각으로 싸워!";
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import GameCanvas from './components/GameCanvas';
import HUD from './components/HUD';
import { GameStatus, GameState, Tank } from './types';
import { 
  CANVAS_WIDTH, 
  CANVAS_HEIGHT, 
  PLAYER_RADIUS, 
  INITIAL_ADVICE,
  PLAYER_SPEED
} from './constants';
import { getGemdoriAdvice } from './services/geminiService';

const App: React.FC = () => {
  const [status, setStatus] = useState<GameStatus>(GameStatus.START);
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [advice, setAdvice] = useState(INITIAL_ADVICE);
  const [isLoadingAdvice, setIsLoadingAdvice] = useState(false);

  const initGame = useCallback(() => {
    const player: Tank = {
      id: 'player',
      pos: { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT / 2 },
      velocity: { x: 0, y: 0 },
      radius: PLAYER_RADIUS,
      angle: 0,
      health: 100,
      maxHealth: 100,
      type: 'player',
      cooldown: 0,
      score: 0,
      speed: PLAYER_SPEED
    };

    setGameState({
      player,
      enemies: [],
      bullets: [],
      particles: [],
      level: 1,
      status: GameStatus.PLAYING,
      advice: INITIAL_ADVICE
    });
    setStatus(GameStatus.PLAYING);
  }, []);

  const handleGameOver = useCallback((finalScore: number) => {
    setStatus(GameStatus.GAMEOVER);
    requestAdvice(`플레이어 사망. 최종 점수: ${finalScore}`);
  }, []);

  const requestAdvice = async (context: string) => {
    if (isLoadingAdvice) return;
    setIsLoadingAdvice(true);
    const newAdvice = await getGemdoriAdvice(context);
    setAdvice(newAdvice);
    setIsLoadingAdvice(false);
  };

  useEffect(() => {
    if (status === GameStatus.PLAYING && gameState?.level) {
      if (gameState.level > 1) {
         requestAdvice(`레벨 ${gameState.level} 도달! 플레이어가 아주 잘하고 있어.`);
      }
    }
  }, [gameState?.level, status]);

  return (
    <div className="relative w-screen h-screen bg-slate-950 flex items-center justify-center overflow-hidden">
      <div className="scanline"></div>

      {/* Background Ambience */}
      <div className="absolute inset-0 opacity-20 pointer-events-none">
        <div className="absolute top-10 left-10 w-64 h-64 bg-blue-500 rounded-full blur-[120px]"></div>
        <div className="absolute bottom-10 right-10 w-64 h-64 bg-red-500 rounded-full blur-[120px]"></div>
      </div>

      <div className="relative z-20 flex flex-col md:flex-row gap-6 p-4 max-w-6xl w-full">
        {/* Left Side: Game View */}
        <div className="flex-1 flex flex-col gap-4">
          <div className="bg-slate-900 border-2 border-slate-700 rounded-xl overflow-hidden shadow-2xl relative">
            {status === GameStatus.START && (
              <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900/90 z-30">
                <div className="mb-6 text-center">
                  <h1 className="text-5xl font-bold text-sky-400 mb-2 tracking-tighter italic">SYMBOLIC TANKS</h1>
                  <p className="text-slate-400">Developed by 20-Year Senior 'Gemdori'</p>
                </div>
                <button 
                  onClick={initGame}
                  className="px-10 py-4 bg-sky-600 hover:bg-sky-500 text-white font-bold rounded-lg transition-all transform hover:scale-105 active:scale-95 shadow-lg flex items-center gap-2"
                >
                  <i className="fas fa-play"></i> GAME START
                </button>
              </div>
            )}

            {status === GameStatus.GAMEOVER && (
              <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-950/90 z-30">
                <h2 className="text-6xl font-black text-white mb-4 italic">CRITICAL DAMAGE!</h2>
                <p className="text-red-200 mb-8 text-xl">실력이 녹슬었구만, 신입?</p>
                <div className="flex gap-4">
                  <button 
                    onClick={initGame}
                    className="px-8 py-3 bg-white text-red-900 font-bold rounded-lg hover:bg-red-100 transition-all"
                  >
                    RETRY
                  </button>
                  <button 
                    onClick={() => setStatus(GameStatus.START)}
                    className="px-8 py-3 border-2 border-white text-white font-bold rounded-lg hover:bg-white/10 transition-all"
                  >
                    QUIT
                  </button>
                </div>
              </div>
            )}

            <GameCanvas 
              status={status} 
              onGameOver={handleGameOver}
              onLevelUp={(lvl) => setGameState(prev => prev ? {...prev, level: lvl} : null)}
              onScoreUpdate={(score) => setGameState(prev => prev ? {...prev, player: {...prev.player, score}} : null)}
            />
          </div>
        </div>

        {/* Right Side: Gemdori Sidebar */}
        <div className="w-full md:w-80 flex flex-col gap-4">
          <div className="bg-slate-900 border-2 border-slate-700 rounded-xl p-6 shadow-xl h-full flex flex-col">
            <div className="flex items-center gap-4 mb-6">
              <div className="w-16 h-16 bg-slate-800 rounded-full border-2 border-sky-500 flex items-center justify-center overflow-hidden">
                <img src="https://picsum.photos/seed/gemdori/200" alt="Gemdori" className="w-full h-full object-cover grayscale" />
              </div>
              <div>
                <h3 className="font-bold text-sky-400">겜돌이 (Senior)</h3>
                <p className="text-xs text-slate-500">20년차 개발 아재</p>
              </div>
            </div>

            <div className="flex-1 bg-black/40 rounded-lg p-4 border border-slate-800 text-sm leading-relaxed mb-4 overflow-y-auto">
              {isLoadingAdvice ? (
                <div className="flex gap-1">
                  <span className="w-2 h-2 bg-sky-500 rounded-full animate-bounce"></span>
                  <span className="w-2 h-2 bg-sky-500 rounded-full animate-bounce delay-75"></span>
                  <span className="w-2 h-2 bg-sky-500 rounded-full animate-bounce delay-150"></span>
                </div>
              ) : (
                <p className="text-slate-300 italic">"{advice}"</p>
              )}
            </div>

            <HUD score={gameState?.player.score || 0} level={gameState?.level || 1} health={gameState?.player.health || 0} />

            <div className="mt-4 pt-4 border-t border-slate-800">
               <div className="text-[10px] text-slate-600 space-y-1 uppercase tracking-widest">
                  <p>Engine: Custom Canvas</p>
                  <p>Logic: Reactive State</p>
                  <p>AI: Gemini Flash 2.5</p>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, 
  Vector, 
  Tank, 
  Bullet, 
  Particle 
} from '../types';
import { 
  CANVAS_WIDTH, 
  CANVAS_HEIGHT, 
  COLORS, 
  PLAYER_SPEED, 
  BULLET_SPEED, 
  SHOOT_COOLDOWN,
  PLAYER_RADIUS,
  ENEMY_RADIUS,
  BULLET_RADIUS
} from '../constants';

interface GameCanvasProps {
  status: GameStatus;
  onGameOver: (score: number) => void;
  onLevelUp: (level: number) => void;
  onScoreUpdate: (score: number) => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ status, onGameOver, onLevelUp, onScoreUpdate }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Game State Refs (avoid React state lag for 60fps)
  const playerRef = useRef<Tank>({
    id: 'player',
    pos: { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT / 2 },
    velocity: { x: 0, y: 0 },
    radius: PLAYER_RADIUS,
    angle: 0,
    health: 100,
    maxHealth: 100,
    type: 'player',
    cooldown: 0,
    score: 0,
    speed: PLAYER_SPEED
  });
  const enemiesRef = useRef<Tank[]>([]);
  const bulletsRef = useRef<Bullet[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const keysRef = useRef<Set<string>>(new Set());
  const mouseRef = useRef<Vector>({ x: 0, y: 0 });
  const levelRef = useRef<number>(1);

  const spawnEnemy = useCallback(() => {
    const side = Math.floor(Math.random() * 4);
    let x, y;
    if (side === 0) { x = Math.random() * CANVAS_WIDTH; y = -50; }
    else if (side === 1) { x = CANVAS_WIDTH + 50; y = Math.random() * CANVAS_HEIGHT; }
    else if (side === 2) { x = Math.random() * CANVAS_WIDTH; y = CANVAS_HEIGHT + 50; }
    else { x = -50; y = Math.random() * CANVAS_HEIGHT; }

    const enemy: Tank = {
      id: Math.random().toString(),
      pos: { x, y },
      velocity: { x: 0, y: 0 },
      radius: ENEMY_RADIUS,
      angle: 0,
      health: 20 + levelRef.current * 10,
      maxHealth: 20 + levelRef.current * 10,
      type: 'enemy',
      cooldown: 60,
      score: 0,
      speed: 1.5 + (levelRef.current * 0.2)
    };
    enemiesRef.current.push(enemy);
  }, []);

  const createExplosion = (pos: Vector, color: string) => {
    for (let i = 0; i < 15; i++) {
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { ...pos },
        velocity: { 
          x: (Math.random() - 0.5) * 6, 
          y: (Math.random() - 0.5) * 6 
        },
        life: 1.0,
        color
      });
    }
  };

  const update = () => {
    if (status !== GameStatus.PLAYING) return;

    const p = playerRef.current;

    // Movement
    let dx = 0, dy = 0;
    if (keysRef.current.has('w') || keysRef.current.has('ArrowUp')) dy -= p.speed;
    if (keysRef.current.has('s') || keysRef.current.has('ArrowDown')) dy += p.speed;
    if (keysRef.current.has('a') || keysRef.current.has('ArrowLeft')) dx -= p.speed;
    if (keysRef.current.has('d') || keysRef.current.has('ArrowRight')) dx += p.speed;

    p.pos.x += dx;
    p.pos.y += dy;

    // Constrain Player
    p.pos.x = Math.max(p.radius, Math.min(CANVAS_WIDTH - p.radius, p.pos.x));
    p.pos.y = Math.max(p.radius, Math.min(CANVAS_HEIGHT - p.radius, p.pos.y));

    // Aiming
    p.angle = Math.atan2(mouseRef.current.y - p.pos.y, mouseRef.current.x - p.pos.x);

    // Shooting
    if (p.cooldown > 0) p.cooldown--;
    if (keysRef.current.has('CLICK') && p.cooldown <= 0) {
      bulletsRef.current.push({
        id: Math.random().toString(),
        ownerId: 'player',
        pos: { 
          x: p.pos.x + Math.cos(p.angle) * p.radius, 
          y: p.pos.y + Math.sin(p.angle) * p.radius 
        },
        velocity: { 
          x: Math.cos(p.angle) * BULLET_SPEED, 
          y: Math.sin(p.angle) * BULLET_SPEED 
        },
        radius: BULLET_RADIUS,
        angle: p.angle,
        health: 1,
        maxHealth: 1,
        damage: 25
      });
      p.cooldown = SHOOT_COOLDOWN;
    }

    // Update Bullets
    bulletsRef.current = bulletsRef.current.filter(b => {
      b.pos.x += b.velocity.x;
      b.pos.y += b.velocity.y;
      return b.pos.x > -50 && b.pos.x < CANVAS_WIDTH + 50 && b.pos.y > -50 && b.pos.y < CANVAS_HEIGHT + 50;
    });

    // Update Enemies
    enemiesRef.current.forEach(e => {
      // Basic AI: Move towards player
      const dist = Math.sqrt((p.pos.x - e.pos.x)**2 + (p.pos.y - e.pos.y)**2);
      const angle = Math.atan2(p.pos.y - e.pos.y, p.pos.x - e.pos.x);
      e.angle = angle;

      if (dist > 150) {
        e.pos.x += Math.cos(angle) * e.speed;
        e.pos.y += Math.sin(angle) * e.speed;
      }

      // Enemy Shoot
      if (e.cooldown > 0) e.cooldown--;
      if (e.cooldown <= 0 && dist < 400) {
        bulletsRef.current.push({
          id: Math.random().toString(),
          ownerId: e.id,
          pos: { x: e.pos.x, y: e.pos.y },
          velocity: { 
            x: Math.cos(angle) * (BULLET_SPEED - 2), 
            y: Math.sin(angle) * (BULLET_SPEED - 2) 
          },
          radius: BULLET_RADIUS,
          angle: angle,
          health: 1,
          maxHealth: 1,
          damage: 10
        });
        e.cooldown = 100 - (levelRef.current * 5);
      }
    });

    // Collisions: Bullet vs Tanks
    bulletsRef.current = bulletsRef.current.filter(b => {
      let hit = false;
      if (b.ownerId === 'player') {
        enemiesRef.current.forEach(e => {
          const d = Math.sqrt((b.pos.x - e.pos.x)**2 + (b.pos.y - e.pos.y)**2);
          if (d < b.radius + e.radius) {
            e.health -= b.damage;
            hit = true;
            createExplosion(b.pos, COLORS.BULLET);
          }
        });
      } else {
        const d = Math.sqrt((b.pos.x - p.pos.x)**2 + (b.pos.y - p.pos.y)**2);
        if (d < b.radius + p.radius) {
          p.health -= b.damage;
          hit = true;
          createExplosion(b.pos, COLORS.PLAYER);
        }
      }
      return !hit;
    });

    // Cleanup Dead Enemies
    enemiesRef.current = enemiesRef.current.filter(e => {
      if (e.health <= 0) {
        p.score += 100;
        onScoreUpdate(p.score);
        createExplosion(e.pos, COLORS.ENEMY);
        return false;
      }
      return true;
    });

    // Check Player Death
    if (p.health <= 0) {
      onGameOver(p.score);
    }

    // Particles
    particlesRef.current.forEach(pt => {
      pt.pos.x += pt.velocity.x;
      pt.pos.y += pt.velocity.y;
      pt.life -= 0.02;
    });
    particlesRef.current = particlesRef.current.filter(pt => pt.life > 0);

    // Level Management
    if (enemiesRef.current.length === 0 && status === GameStatus.PLAYING) {
      levelRef.current += 1;
      onLevelUp(levelRef.current);
      for (let i = 0; i < levelRef.current + 1; i++) {
        spawnEnemy();
      }
    }
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw Grid
    ctx.strokeStyle = COLORS.GRID;
    ctx.lineWidth = 1;
    for (let x = 0; x < CANVAS_WIDTH; x += 50) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, CANVAS_HEIGHT);
      ctx.stroke();
    }
    for (let y = 0; y < CANVAS_HEIGHT; y += 50) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(CANVAS_WIDTH, y);
      ctx.stroke();
    }

    // Draw Particles
    particlesRef.current.forEach(pt => {
      ctx.globalAlpha = pt.life;
      ctx.fillStyle = pt.color;
      ctx.fillRect(pt.pos.x, pt.pos.y, 3, 3);
    });
    ctx.globalAlpha = 1.0;

    // Draw Bullets
    bulletsRef.current.forEach(b => {
      ctx.fillStyle = COLORS.BULLET;
      ctx.beginPath();
      ctx.arc(b.pos.x, b.pos.y, b.radius, 0, Math.PI * 2);
      ctx.fill();
      // Glow effect
      ctx.shadowBlur = 10;
      ctx.shadowColor = COLORS.BULLET;
      ctx.stroke();
      ctx.shadowBlur = 0;
    });

    // Draw Enemies
    enemiesRef.current.forEach(e => {
      ctx.save();
      ctx.translate(e.pos.x, e.pos.y);
      ctx.rotate(e.angle);

      // Symbol: Red Square Tank
      ctx.fillStyle = COLORS.ENEMY;
      ctx.fillRect(-e.radius, -e.radius, e.radius * 2, e.radius * 2);
      // Barrel
      ctx.fillStyle = '#b91c1c';
      ctx.fillRect(e.radius * 0.5, -5, e.radius * 1.2, 10);

      ctx.restore();

      // Health Bar
      ctx.fillStyle = '#444';
      ctx.fillRect(e.pos.x - 20, e.pos.y - 30, 40, 5);
      ctx.fillStyle = COLORS.ENEMY;
      ctx.fillRect(e.pos.x - 20, e.pos.y - 30, 40 * (e.health / e.maxHealth), 5);
    });

    // Draw Player
    const p = playerRef.current;
    ctx.save();
    ctx.translate(p.pos.x, p.pos.y);
    ctx.rotate(p.angle);

    // Symbol: Blue Circle Tank
    ctx.fillStyle = COLORS.PLAYER;
    ctx.beginPath();
    ctx.arc(0, 0, p.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#0284c7';
    ctx.lineWidth = 3;
    ctx.stroke();

    // Barrel
    ctx.fillStyle = COLORS.PLAYER;
    ctx.fillRect(p.radius * 0.5, -6, p.radius * 1.5, 12);

    ctx.restore();
  };

  const gameLoop = useCallback(() => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (ctx) {
      update();
      draw(ctx);
    }
    requestRef.current = requestAnimationFrame(gameLoop);
  }, [status]);

  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      // Reset game state when starting fresh
      playerRef.current = {
        ...playerRef.current,
        pos: { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT / 2 },
        health: 100,
        score: 0
      };
      levelRef.current = 1;
      enemiesRef.current = [];
      bulletsRef.current = [];
      particlesRef.current = [];
      spawnEnemy();
    }
  }, [status, spawnEnemy]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);

    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.key.toLowerCase());
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.key.toLowerCase());
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if (rect) {
        mouseRef.current = {
          x: e.clientX - rect.left,
          y: e.clientY - rect.top
        };
      }
    };
    const handleMouseDown = () => keysRef.current.add('CLICK');
    const handleMouseUp = () => keysRef.current.delete('CLICK');

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [gameLoop]);

  return (
    <canvas 
      ref={canvasRef} 
      width={CANVAS_WIDTH} 
      height={CANVAS_HEIGHT}
      className="w-full h-auto cursor-crosshair bg-[#0f172a]"
    />
  );
};

export default GameCanvas;

import React from 'react';

interface HUDProps {
  score: number;
  level: number;
  health: number;
}

const HUD: React.FC<HUDProps> = ({ score, level, health }) => {
  return (
    <div className="space-y-4">
      <div className="flex justify-between items-end">
        <div>
          <p className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Score</p>
          <p className="text-3xl font-black text-white">{score.toLocaleString()}</p>
        </div>
        <div className="text-right">
          <p className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Level</p>
          <p className="text-xl font-bold text-sky-400">STAGE {level}</p>
        </div>
      </div>

      <div className="space-y-1">
        <div className="flex justify-between text-[10px] uppercase font-bold text-slate-400 tracking-wider">
