import React, { useState, useEffect, useRef } from 'react';

interface MobileControlsProps {
  onMove: (vector: { x: number; y: number }) => void;
  onFire: (isFiring: boolean) => void;
}

const MobileControls: React.FC<MobileControlsProps> = ({ onMove, onFire }) => {
  const [joystickPos, setJoystickPos] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const joystickBaseRef = useRef<HTMLDivElement>(null);

  const handleTouchMove = (e: React.TouchEvent) => {
    if (!isDragging || !joystickBaseRef.current) return;

    const touch = e.touches[0];
    const rect = joystickBaseRef.current.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;

    let dx = touch.clientX - centerX;
    let dy = touch.clientY - centerY;

    const distance = Math.sqrt(dx * dx + dy * dy);
    const maxRadius = rect.width / 2;

    if (distance > maxRadius) {
      dx = (dx / distance) * maxRadius;
      dy = (dy / distance) * maxRadius;
    }

    setJoystickPos({ x: dx, y: dy });
    onMove({ x: dx / maxRadius, y: dy / maxRadius });
  };

  const handleTouchEnd = () => {
    setIsDragging(false);
    setJoystickPos({ x: 0, y: 0 });
    onMove({ x: 0, y: 0 });
  };

  return (
    <div className="absolute inset-0 pointer-events-none select-none z-40 lg:hidden">
      {/* Joystick Area */}
      <div 
        className="absolute bottom-12 left-12 w-32 h-32 bg-slate-800/30 rounded-full border-2 border-slate-700/50 pointer-events-auto touch-none"
        ref={joystickBaseRef}
        onTouchStart={() => setIsDragging(true)}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
      >
        <div 
          className="absolute w-12 h-12 bg-sky-500/50 rounded-full border-2 border-sky-400 shadow-lg transform -translate-x-1/2 -translate-y-1/2 transition-transform duration-75"
          style={{ 
            left: `calc(50% + ${joystickPos.x}px)`, 
            top: `calc(50% + ${joystickPos.y}px)` 
          }}
        />
      </div>

      {/* Fire Button */}
      <div 
        className="absolute bottom-12 right-12 w-24 h-24 bg-red-600/30 rounded-full border-2 border-red-500/50 flex items-center justify-center pointer-events-auto touch-none active:bg-red-500/50 active:scale-95 transition-all"
        onTouchStart={() => onFire(true)}
        onTouchEnd={() => onFire(false)}
      >
        <span className="text-red-100 font-black text-xl italic tracking-tighter">FIRE</span>
      </div>
    </div>
  );
};

export default MobileControls;

